// O3 for the other generators: every group of the JSON-Schema-Test-Suite that the Rust harness
// runs, wrapped into an OpenAPI 3.1 document, generated by each tool (one Node process per
// tool), its cases written as the harness writes them, and one compiler run per tool. flowapi's
// figures are read from conformance/results/suite.json. Writes conformance/results/compare.*.
//
//     node conformance/compare/compare.mjs
import { spawnSync } from 'node:child_process'
import { mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { suite } from './load.mjs'
import { json, markdown } from './report.mjs'
import { check, judge } from './tsc.mjs'
import { wrap } from './wrap.mjs'

const here = dirname(fileURLToPath(import.meta.url))
const conformance = join(here, '..')
const repo = join(conformance, '..')
const tsc = join(conformance, 'ts/node_modules/.bin/tsc')
const version = (dir) => JSON.parse(readFileSync(join(dir, 'package.json'), 'utf8')).version
const competitors = join(repo, 'bench/competitors/node_modules')

const TOOLS = [
  { id: 'openapi-typescript', package: 'openapi-typescript' },
  { id: 'hey-api', package: '@hey-api/openapi-ts' },
]

// No path of this machine in the results.
const scrub = (s) => s.split(repo).join('<repo>').split(tmpdir()).join('<tmp>')

function run(files, tool) {
  const out = join(here, 'out', tool.id)
  rmSync(out, { recursive: true, force: true })
  mkdirSync(out, { recursive: true })
  const jobs = []
  for (const f of files) {
    for (const g of f.groups.filter((x) => x.admission === 'run')) {
      jobs.push({ name: `${f.name}-${g.index}`, document: wrap(f.name, g) })
    }
  }
  const input = join(out, 'documents.json')
  const output = join(out, 'generated.json')
  writeFileSync(input, JSON.stringify(jobs))
  const started = Date.now()
  const child = spawnSync(process.execPath, [join(here, 'generate.mjs'), tool.id, input, output], {
    stdio: ['ignore', 'ignore', 'pipe'],
    encoding: 'utf8',
    maxBuffer: 1 << 30,
  })
  // What the tools print on their way (warnings, failures already recorded) is shown only when
  // the process itself failed.
  if (child.status !== 0) throw new Error(`${tool.id}: the generator process failed (${child.status})\n${child.stderr}`)
  const generated = new Map(JSON.parse(readFileSync(output, 'utf8')).map((r) => [r.name, r]))
  const generateMs = Date.now() - started

  const written = []
  const firstLine = new Map()
  for (const f of files) {
    for (const g of f.groups.filter((x) => x.admission === 'run')) {
      const name = `${f.name}-${g.index}`
      const r = generated.get(name)
      if (r.error !== undefined) continue
      let text = r.types
      // A file that exports nothing would be a script, its `Root` shared with every other file.
      if (!/^export /m.test(text)) text += 'export {};\n'
      firstLine.set(name, text.split('\n').length)
      text += g.cases.map((c, i) => `const c${i}: Root = ${c.data};\n`).join('')
      writeFileSync(join(out, `${name}.ts`), text)
      written.push(`${name}.ts`)
    }
  }
  const started2 = Date.now()
  const diagnostics = check(tsc, out, written)
  const checkMs = Date.now() - started2

  const perFile = files.map((f) => {
    const r = { name: f.name, groups: f.groups.length, run: 0, generationErrors: [], invalidTs: [] }
    Object.assign(r, { valid: 0, validAccepted: 0, invalid: 0, invalidRejected: 0, unsound: [], ok: new Map() })
    for (const g of f.groups.filter((x) => x.admission === 'run')) {
      r.run++
      const name = `${f.name}-${g.index}`
      const gen = generated.get(name)
      const fail = (message) => ({ group: g.index, description: g.description, message: scrub(message) })
      if (gen.error !== undefined) {
        r.generationErrors.push(fail(gen.error))
        continue
      }
      const v = judge(g, `${name}.ts`, firstLine.get(name), diagnostics)
      if (v.invalidTs !== undefined) {
        r.invalidTs.push(fail(v.invalidTs))
        continue
      }
      r.valid += v.valid
      r.validAccepted += v.validAccepted
      r.invalid += v.invalid
      r.invalidRejected += v.invalidRejected
      r.ok.set(g.index, { valid: v.valid, accepted: v.validAccepted })
      for (const u of v.unsound) {
        r.unsound.push({ group: g.index, group_description: g.description, ...u, error: scrub(u.error) })
      }
    }
    return r
  })
  console.error(`${tool.id}: generated in ${generateMs} ms, checked in ${checkMs} ms`)
  return { id: tool.id, version: version(join(competitors, tool.package)), files: perFile, other: diagnostics.other.map(scrub) }
}

// flowapi's run, from the harness's committed results, in the same shape.
function flowapi(files) {
  const results = JSON.parse(readFileSync(join(conformance, 'results/suite.json'), 'utf8'))
  const perFile = files.map((f) => {
    const s = results.files[f.name]
    const failed = new Set([...s.generation_errors, ...s.invalid_typescript].map((x) => x.group))
    const ok = new Map()
    for (const g of f.groups.filter((x) => x.admission === 'run' && !failed.has(x.index))) {
      const valid = g.cases.filter((c) => c.valid).length
      const unsound = s.unsound.filter((u) => u.group === g.index).length
      ok.set(g.index, { valid, accepted: valid - unsound })
    }
    return {
      name: f.name,
      groups: s.groups,
      run: s.groups - s.skipped_dialect - s.skipped_format_assertion,
      generationErrors: s.generation_errors,
      invalidTs: s.invalid_typescript,
      valid: s.valid_cases,
      validAccepted: s.valid_accepted,
      invalid: s.invalid_cases,
      invalidRejected: s.invalid_rejected,
      unsound: s.unsound,
      ok,
    }
  })
  // The crate takes its version from the workspace (`version.workspace = true`).
  const cargo = readFileSync(join(repo, 'Cargo.toml'), 'utf8')
  const v = /^version\s*=\s*"([^"]+)"/m.exec(cargo)?.[1] ?? 'unknown'
  return { id: 'flowapi', version: v, files: perFile, other: results.compiler_other }
}

const files = suite(join(conformance, 'suites/json-schema-test-suite/tests'))
const tools = [flowapi(files), ...TOOLS.map((t) => run(files, t))]
const meta = { typescript: version(join(conformance, 'ts/node_modules/typescript')) }
mkdirSync(join(conformance, 'results'), { recursive: true })
writeFileSync(join(conformance, 'results/compare.json'), json(tools, meta))
writeFileSync(join(conformance, 'results/compare.md'), markdown(tools, meta))
console.error('results in conformance/results/compare.json and compare.md')
